<?php
declare(strict_types=1);

function entra_sso_ready():bool{return app_setting('entra_sso_enabled')==='1'&&app_setting('entra_sso_tenant_id')!==''&&app_setting('entra_sso_client_id')!==''&&app_setting('entra_sso_client_secret_enc')!=='';}
function entra_b64url(string $value):string{return rtrim(strtr(base64_encode($value),'+/','-_'),'=');}
function entra_json_request(string $url,string $method='GET',array $headers=[],?string $body=null):array{
    $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>30,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_REDIR_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_HTTPHEADER=>$headers,CURLOPT_POSTFIELDS=>$body]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_error($ch);curl_close($ch);$data=json_decode((string)$raw,true);if($status<200||$status>=300)throw new RuntimeException('Microsoft authentication failed ('.$status.'): '.mb_strimwidth((string)($data['error_description']??$data['error']['message']??$error?:'Unknown response'),0,300,'…'));return is_array($data)?$data:[];
}
function entra_id_claims(string $token):array{$parts=explode('.',$token);if(count($parts)!==3)return [];$raw=base64_decode(strtr($parts[1],'-_','+/'),true);$claims=json_decode((string)$raw,true);return is_array($claims)?$claims:[];}
function crm_complete_login(array $account,string $returnTo='/',string $action='login'):never{
    session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(32));$_SESSION['user']=['id'=>(int)$account['id'],'role_id'=>(int)$account['role_id'],'username'=>$account['username'],'is_admin'=>(bool)$account['is_admin'],'permissions'=>json_decode($account['permissions_json']??'[]',true),'force_password_change'=>(bool)$account['force_password_change']];db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$account['id']]);audit($action,'user',(int)$account['id']);redirect($account['force_password_change']?'/change-password':safe_return_path($returnTo));
}

if($path==='/admin/sso'){
    require_login();if(!(user()['is_admin']??false)){http_response_code(403);exit('Forbidden');}
    if($method==='POST'){
        verify_csrf();$tenant=trim((string)post('tenant_id'));$client=trim((string)post('client_id'));$role=(int)post('default_role_id');
        if(($tenant!==''&&!preg_match('/^[a-zA-Z0-9.-]{2,190}$/',$tenant))||($client!==''&&!preg_match('/^[a-f0-9-]{36}$/i',$client))){flash('error','Enter a valid tenant ID/domain and application client ID.');redirect('/admin/sso');}
        if($role){$q=db()->prepare('SELECT COUNT(*) FROM roles WHERE id=?');$q->execute([$role]);if(!$q->fetchColumn())$role=0;}
        $values=['entra_sso_enabled'=>post('enabled')?'1':'0','entra_sso_tenant_id'=>$tenant,'entra_sso_client_id'=>$client,'entra_sso_match_email'=>post('match_email')?'1':'0','entra_sso_jit_enabled'=>post('jit_enabled')?'1':'0','entra_sso_default_role_id'=>$role?(string)$role:''];if((string)post('client_secret')!=='')$values['entra_sso_client_secret_enc']=encrypt_secret((string)post('client_secret'));$save=db()->prepare('INSERT INTO app_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($values as $key=>$value)$save->execute([$key,$value]);app_settings(true);audit('update','entra_sso_settings',null,['enabled'=>$values['entra_sso_enabled'],'tenant'=>$tenant,'client_id_suffix'=>$client!==''?substr($client,-6):'','match_email'=>$values['entra_sso_match_email'],'jit'=>$values['entra_sso_jit_enabled'],'default_role_id'=>$role]);flash('success',entra_sso_ready()?'Microsoft SSO settings saved and enabled.':'Microsoft SSO settings saved. Complete all required fields before enabling it.');redirect('/admin/sso');
    }
    $s=app_settings();$roles=db()->query('SELECT id,name FROM roles ORDER BY name')->fetchAll();$callback=rtrim((string)config('url'),'/').'/auth/microsoft/callback';layout('Microsoft SSO',function()use($s,$roles,$callback){?><h1>Microsoft Entra ID single sign-on</h1><div class="card"><p>Register a Microsoft Entra web application and add this exact redirect URI:</p><p><code><?=e($callback)?></code></p><p class="muted">The application requests OpenID identity scopes and Microsoft Graph User.Read.</p></div><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><label><input style="width:auto" type="checkbox" name="enabled" value="1" <?=$s['entra_sso_enabled']==='1'?'checked':''?>> Enable Microsoft sign-in</label><div class="form-grid"><label>Directory (tenant) ID or verified tenant domain<input name="tenant_id" value="<?=e($s['entra_sso_tenant_id'])?>" placeholder="00000000-0000-0000-0000-000000000000" required></label><label>Application (client) ID<input name="client_id" value="<?=e($s['entra_sso_client_id'])?>" placeholder="00000000-0000-0000-0000-000000000000" required></label><label class="full">Client secret value<input type="password" name="client_secret" autocomplete="new-password" placeholder="<?=$s['entra_sso_client_secret_enc']?'Stored — leave blank to keep':'Paste the secret value'?>"></label></div><label><input style="width:auto" type="checkbox" name="match_email" value="1" <?=$s['entra_sso_match_email']==='1'?'checked':''?>> Link an existing active CRM user when its email matches the Microsoft account</label><label><input style="width:auto" type="checkbox" name="jit_enabled" value="1" <?=$s['entra_sso_jit_enabled']==='1'?'checked':''?>> Automatically create CRM users after their first successful Microsoft sign-in</label><label>Role for automatically created users<select name="default_role_id"><option value="">No role</option><?php foreach($roles as $role):?><option value="<?=$role['id']?>" <?=$s['entra_sso_default_role_id']==$role['id']?'selected':''?>><?=e($role['name'])?></option><?php endforeach?></select></label><p class="muted">Leave automatic creation off if administrators should create every account in advance. Local password sign-in remains available.</p><button>Save Microsoft SSO settings</button></form><?php });exit;
}

if($path==='/auth/microsoft'){
    if(!entra_sso_ready()){flash('error','Microsoft sign-in is not available.');redirect('/login');}$state=bin2hex(random_bytes(24));$nonce=bin2hex(random_bytes(24));$verifier=entra_b64url(random_bytes(48));$returnTo=safe_return_path($_GET['return']??'/');$_SESSION['entra_oauth']=['state'=>$state,'nonce'=>$nonce,'verifier'=>$verifier,'return'=>$returnTo,'time'=>time()];$redirectUri=rtrim((string)config('url'),'/').'/auth/microsoft/callback';$params=['client_id'=>app_setting('entra_sso_client_id'),'response_type'=>'code','redirect_uri'=>$redirectUri,'response_mode'=>'query','scope'=>'openid profile email User.Read','state'=>$state,'nonce'=>$nonce,'code_challenge'=>entra_b64url(hash('sha256',$verifier,true)),'code_challenge_method'=>'S256','prompt'=>'select_account'];redirect('https://login.microsoftonline.com/'.rawurlencode(app_setting('entra_sso_tenant_id')).'/oauth2/v2.0/authorize?'.http_build_query($params));
}

if($path==='/auth/microsoft/callback'){
    $saved=$_SESSION['entra_oauth']??[];unset($_SESSION['entra_oauth']);if(!entra_sso_ready()||!hash_equals((string)($saved['state']??''),(string)($_GET['state']??''))||time()-(int)($saved['time']??0)>600){http_response_code(400);exit('Invalid or expired Microsoft sign-in request.');}if(isset($_GET['error'])){app_log('warning','Microsoft SSO declined',['error'=>(string)$_GET['error']]);flash('error','Microsoft sign-in was cancelled or denied.');redirect('/login');}
    try{$redirectUri=rtrim((string)config('url'),'/').'/auth/microsoft/callback';$tenant=app_setting('entra_sso_tenant_id');$body=http_build_query(['client_id'=>app_setting('entra_sso_client_id'),'client_secret'=>decrypt_secret(app_setting('entra_sso_client_secret_enc')),'code'=>(string)($_GET['code']??''),'grant_type'=>'authorization_code','redirect_uri'=>$redirectUri,'scope'=>'openid profile email User.Read','code_verifier'=>(string)$saved['verifier']]);$token=entra_json_request('https://login.microsoftonline.com/'.rawurlencode($tenant).'/oauth2/v2.0/token','POST',['Content-Type: application/x-www-form-urlencoded'],$body);$claims=entra_id_claims((string)($token['id_token']??''));if(!hash_equals((string)$saved['nonce'],(string)($claims['nonce']??''))||!hash_equals(app_setting('entra_sso_client_id'),(string)($claims['aud']??'')))throw new RuntimeException('Microsoft identity token validation failed.');$profile=entra_json_request('https://graph.microsoft.com/v1.0/me?$select=id,displayName,mail,userPrincipalName','GET',['Authorization: Bearer '.(string)$token['access_token']]);$oid=trim((string)($profile['id']??''));$email=mb_strtolower(trim((string)($profile['mail']??$profile['userPrincipalName']??'')));if(!preg_match('/^[a-f0-9-]{36}$/i',$oid)||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Microsoft did not return a usable account identifier and email address.');$q=db()->prepare('SELECT u.*,r.permissions_json FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE u.entra_object_id=? AND u.active=1 LIMIT 1');$q->execute([$oid]);$account=$q->fetch();if(!$account&&app_setting('entra_sso_match_email')==='1'){$q=db()->prepare('SELECT u.*,r.permissions_json FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE LOWER(u.email)=? AND u.active=1 LIMIT 1');$q->execute([$email]);$account=$q->fetch();if($account){db()->prepare('UPDATE users SET entra_object_id=? WHERE id=?')->execute([$oid,$account['id']]);$account['entra_object_id']=$oid;audit('link_microsoft_sso','user',(int)$account['id']);}}if(!$account&&app_setting('entra_sso_jit_enabled')==='1'){$base=mb_substr(preg_replace('/[^a-z0-9._-]+/','',mb_strtolower(strstr($email,'@',true)?:'user')),0,65)?:'user';$username=$base;$n=1;$check=db()->prepare('SELECT COUNT(*) FROM users WHERE LOWER(username)=?');while(true){$check->execute([mb_strtolower($username)]);if(!$check->fetchColumn())break;$username=mb_substr($base,0,70-strlen((string)$n)).'-'.$n++;}$role=(int)app_setting('entra_sso_default_role_id');db()->prepare('INSERT INTO users(role_id,username,display_name,email,password_hash,entra_object_id,is_admin,force_password_change,active) VALUES(?,?,?,?,?,?,0,0,1)')->execute([$role?:null,$username,trim((string)($profile['displayName']??$username)),$email,password_hash(entra_b64url(random_bytes(48)),PASSWORD_DEFAULT),$oid]);$id=(int)db()->lastInsertId();$q=db()->prepare('SELECT u.*,r.permissions_json FROM users u LEFT JOIN roles r ON r.id=u.role_id WHERE u.id=?');$q->execute([$id]);$account=$q->fetch();audit('provision_microsoft_sso','user',$id,['email'=>$email,'role_id'=>$role?:null]);}if(!$account)throw new RuntimeException('No active CRM account is linked to this Microsoft identity. Ask an administrator to create or link your account.');crm_complete_login($account,(string)($saved['return']??'/'),'login_microsoft');}catch(Throwable $e){app_log('warning','Microsoft SSO rejected',['error'=>$e->getMessage()]);flash('error',$e->getMessage());redirect('/login');}
}
